mapper.select:
SELECT id, job_name, job_cn_name, job_type, source_datasource_id, source_database, source_table, target_database, target_table, engine_type, schedule_frequency, is_monitored, job_version_id, online_version, status, description, last_publish_time, create_time, update_time, create_by, creator_id, update_by, last_publish_by, last_publish_by_id FROM etl_job
AND job_name LIKE CONCAT(#{req.jobName}, '%')
AND job_cn_name LIKE CONCAT(#{req.jobCnName}, '%')
AND job_type = #{req.jobType}
AND status = #{req.status}
AND source_datasource_id = #{req.sourceDatasourceId}
AND source_database = #{req.sourceDatabase}
AND source_table LIKE CONCAT(#{req.sourceTable}, '%')
AND schedule_frequency = #{req.scheduleFrequency}
ORDER BY update_time DESC
